-- The tables db.py created in Neon for the Streamlit app. IF NOT EXISTS so this runs as a no-op
-- there and creates them in a fresh database (local PGlite, tests). Foreign keys are inline, as
-- db.py wrote them, so Postgres names them the same way in both.
CREATE TABLE IF NOT EXISTS "users" (
	"id" text PRIMARY KEY NOT NULL,
	"email" text,
	"name" text,
	"created_at" text NOT NULL,
	"last_seen_at" text NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "portfolios" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"user_id" text NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
	"name" text NOT NULL,
	"created_at" text NOT NULL,
	"updated_at" text NOT NULL,
	CONSTRAINT "portfolios_user_id_name_key" UNIQUE("user_id","name")
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "holdings" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"portfolio_id" bigint NOT NULL REFERENCES "portfolios"("id") ON DELETE CASCADE,
	"position" integer NOT NULL,
	"ticker" text NOT NULL,
	"shares" double precision NOT NULL,
	"avg_price" double precision,
	"currency" text,
	"account" text
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "ix_portfolios_user" ON "portfolios" USING btree ("user_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "ix_holdings_portfolio" ON "holdings" USING btree ("portfolio_id");
